INSERT INTO ai_reports (run_id, run_type, user_id, title, summary, content_json, generated_at, read_at, feedback, next_goals) VALUES ('sd00005v', 'weekly_report', 'sd000002', '11월 2주차 주간 리포트 (11/9~11/15)', '이번 주 11개 미션 중 9개를 완료했어요(82%). 푸쉬업 챌린지를 5일 성공해 완주했고, 새 목표 "주 3회 맨몸 운동"도 모두 마쳤어요.', '{"highlights":["푸쉬업 챌린지 5일 성공으로 완주","목표 \"주 3회 맨몸 운동\" 4개 미션 모두 완료","12일에는 수행 기록이 없었어요"]}'::jsonb, timestamptz '2026-11-16 00:12:00+09', timestamptz '2026-11-16 08:00:00+09', '수행한 날은 꾸준히 성공했어요. 쉬는 날을 하루만 줄여도 연속 기록이 훨씬 길어져요.', '[{"categoryCode":"exercise","text":"다음 주에는 스쿼트 챌린지에 도전해 보세요"},{"categoryCode":"exercise","text":"러닝 1km를 일정에 넣어 보세요"}]'::jsonb);
