-- 데모 시드 (기간 2026-11-16 ~ 2026-11-23, 기준일 11-18)
-- 사용자 5명(이광수·김영희·박철수·이민수·최지우), 관리자 admin_kim, 챌린지 2개, 펫(알·아기·성체)
-- 새 행의 ID는 모두 'sd'로 시작한다. 지우려면 002_demo_week_cleanup.sql을 실행한다.
--
-- 실행:
--   psql "$DATABASE_URL" -v admin_password_hash='<해시>' -v user_password_hash='<해시>' -f db/seeds/demo/001_demo_week.sql
-- 선행 조건: seeds/dev 001·002, 펫 종류(늑대·판다·원숭이), 상점 상품(pet_snack)
-- (dev 시드 폴더에 넣지 않은 이유: verify-docker.sh가 빈 DB에서 dev 시드를 모두 돌릴 때 선행 조건 때문에 실패하지 않게 하려는 것)
-- 로그인 정보는 db/seeds/demo/README.md 참고
--
-- 주의
--   * 과거 시각의 챌린지 참여·펫 성장·원장 행을 직접 넣기 위해 트랜잭션 안에서만
--     session_replication_role = replica 로 트리거(FK 포함)를 끈다. CHECK·UNIQUE는 그대로 동작한다.
--   * 성체 펫 경험치(450)와 먹이기 기록은 일주일 한도로는 쌓일 수 없어 '시드 보정 지급(seed_grant)'으로 채웠다.
--   * 영상 파일은 메타데이터만 있다. R2/MinIO에 실제 객체가 없어 관리자 웹에서 재생되지 않는다.

\if :{?admin_password_hash}
\else
    \echo 'Set -v admin_password_hash=<hash> before running this seed.'
    \quit
\endif
\if :{?user_password_hash}
\else
    \echo 'Set -v user_password_hash=<hash> before running this seed.'
    \quit
\endif

BEGIN;
SET LOCAL session_replication_role = replica;

CREATE TEMP TABLE _ref (k text PRIMARY KEY, v text NOT NULL) ON COMMIT DROP;
SELECT 'rate_' || d.code,
       (SELECT r.id FROM mission_reward_rate_versions r
         WHERE r.category_id = (SELECT v FROM _ref WHERE k = 'cat') AND r.difficulty_id = d.id
         ORDER BY r.version_no DESC LIMIT 1)
  FROM difficulty_levels d;
 WHERE verification_method = 'camera' ORDER BY version_no DESC LIMIT 1;
 WHERE verification_method = 'sensor' ORDER BY version_no DESC LIMIT 1;
SELECT 'doc_' || t.t, (SELECT id FROM policy_document_versions WHERE document_type = t.t ORDER BY effective_at DESC LIMIT 1)
  FROM (VALUES ('terms'), ('privacy'), ('marketing')) AS t(t);
SELECT 'sp_' || m.k, v.species_id
  FROM (VALUES ('wolf', '늑대'), ('panda', '판다'), ('monkey', '원숭이')) AS m(k, n)
  JOIN LATERAL (SELECT species_id FROM pet_species_versions WHERE name = m.n ORDER BY effective_at DESC LIMIT 1) v ON true;
SELECT 'spv_' || m.k, v.id
  FROM (VALUES ('wolf', '늑대'), ('panda', '판다'), ('monkey', '원숭이')) AS m(k, n)
  JOIN LATERAL (SELECT id FROM pet_species_versions WHERE name = m.n ORDER BY effective_at DESC LIMIT 1) v ON true;
SELECT 'ach_' || d.code, d.id
  FROM achievement_definitions d WHERE d.code IN ('first_goal', 'challenge_1');
SELECT 'achv_' || d.code, v.id
  FROM achievement_definitions d
  JOIN LATERAL (SELECT id FROM achievement_versions WHERE achievement_id = d.id ORDER BY version_no DESC LIMIT 1) v ON true
 WHERE d.code IN ('first_goal', 'challenge_1');
SELECT 'badge_' || d.code, v.badge_image_id
  FROM achievement_definitions d
  JOIN LATERAL (SELECT badge_image_id FROM achievement_versions WHERE achievement_id = d.id ORDER BY version_no DESC LIMIT 1) v ON true
 WHERE d.code IN ('first_goal', 'challenge_1');
SELECT 'shop_price', id FROM shop_item_price_versions
 WHERE item_id = (SELECT v FROM _ref WHERE k = 'shop_item') ORDER BY version_no DESC LIMIT 1;

-- 선행 조건과 중복 실행 확인
DO $chk$
BEGIN
    IF (SELECT count(*) FROM _ref WHERE k IN ('cat', 'diff_easy', 'diff_normal', 'diff_hard', 'rate_easy', 'rate_normal',
        'crit_camera', 'crit_sensor', 'doc_terms', 'doc_privacy', 'doc_marketing', 'lvl_policy', 'pet_lvl_policy',
        'sp_wolf', 'sp_panda', 'sp_monkey', 'spv_wolf', 'spv_panda', 'spv_monkey',
        'ach_first_goal', 'ach_challenge_1', 'achv_first_goal', 'achv_challenge_1', 'badge_first_goal', 'badge_challenge_1',
        'shop_item', 'shop_price')) < 27 THEN
        RAISE EXCEPTION 'reference data missing: check _ref (분야·난이도·인증 기준·약관·레벨 정책·펫 종류·업적·상점)';
    END IF;
    IF EXISTS (SELECT 1 FROM users WHERE id LIKE 'sd%') OR EXISTS (SELECT 1 FROM admin_accounts WHERE id LIKE 'sd%') THEN
        RAISE EXCEPTION 'demo seed already applied: run 002_demo_week_cleanup.sql first';
    END IF;
    IF EXISTS (SELECT 1 FROM profiles WHERE lower(nickname) IN ('이광수', '김영희', '박철수', '이민수', '최지우')) THEN
        RAISE EXCEPTION 'nickname conflict with existing users';
    END IF;
END
$chk$;


UPDATE profiles SET representative_pet_id = 'sd000065', representative_achievement_id = 'sd000061' WHERE user_id = 'sd000002';

-- 검증: 지갑 잔액 = 원장 마지막 잔액, 펫 경험치 = 먹인 합계
DO $verify$
BEGIN
    IF EXISTS (SELECT 1 FROM point_wallets w WHERE w.user_id LIKE 'sd%' AND w.available_points <>
        COALESCE((SELECT balance_after FROM point_transactions t WHERE t.user_id = w.user_id ORDER BY occurred_at DESC, id DESC LIMIT 1), 0)) THEN
        RAISE EXCEPTION 'wallet balance mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM user_pets p WHERE p.user_id LIKE 'sd%' AND p.total_xp <>
        COALESCE((SELECT -sum(xp_delta) FROM pet_xp_wallet_transactions x WHERE x.user_pet_id = p.id AND x.kind = 'feed'), 0)) THEN
        RAISE EXCEPTION 'pet xp mismatch';
    END IF;
END
$verify$;

COMMIT;
